$base = "C:\Users\olive_\OneDrive\Documentos\codigo"
$results = New-Object System.Collections.Generic.List[string]
$stack = New-Object System.Collections.Stack
$stack.Push($base)
while ($stack.Count -gt 0) {
    $current = $stack.Pop()
    if (Test-Path (Join-Path $current ".git")) {
        $results.Add($current)
        continue  # do not descend into a repo (avoids nested node_modules and treats repo as unit)
    }
    Get-ChildItem -LiteralPath $current -Directory -Force -ErrorAction SilentlyContinue | Where-Object {
        $_.Name -ne "node_modules" -and $_.Name -ne ".git"
    } | ForEach-Object { $stack.Push($_.FullName) }
}
$results | Sort-Object

