$base = "C:\Users\olive_\OneDrive\Documentos\codigo"
$msg1 = "backup: migracao de PC (2026-06-30)"
$msg2 = "Co-Authored-By: Claude Opus 4.8 (1M context) <noreply@anthropic.com>"
$bdate = "20260630"

$repos = @(
  @{ p="AI\AssistenteExecutivo-ia";              tag="assistente" },
  @{ p="AI\darcy\css-chat-bubble-style";         tag="AI-darcy-css" },
  @{ p="AI\darcy\css-chat-bubble-style-old";     tag="AI-darcy-css-old" },
  @{ p="AI\eventsnow\now-vents-pulse";           tag="eventsnow-nowvents" },
  @{ p="AI\Truver\now-vents-pulse";              tag="Truver-nowvents" },
  @{ p="chatbubble\css-chat-bubble-style";       tag="chatbubble-css" },
  @{ p="darcy\css-chat-bubble-style";            tag="darcy-css" },
  @{ p="GranaGrana";                             tag="GranaGrana" },
  @{ p="precisionai\green-leaf-scale-main";      tag="greenleaf-main" },
  @{ p="worki\worki12";                          tag="worki12" }
)

foreach ($repo in $repos) {
  $r = Join-Path $base $repo.p
  Write-Output "================================================================"
  Write-Output "REPO: $($repo.p)"
  $branch = git -C $r symbolic-ref --short HEAD 2>$null
  Write-Output "  branch local: $branch"

  $dirty = (git -C $r status --porcelain 2>$null | Measure-Object -Line).Lines
  if ($dirty -gt 0) {
    git -C $r add -A 2>&1 | Out-Null
    git -C $r commit -m $msg1 -m $msg2 2>&1 | Out-Null
    if ($?) { Write-Output "  commit: OK ($dirty arquivos)" } else { Write-Output "  commit: FALHOU" }
  } else {
    Write-Output "  commit: nada a commitar"
  }

  $bkbranch = "backup/migracao-$bdate-$($repo.tag)"
  $pushout = git -C $r push origin "HEAD:$branch" 2>&1 | Out-String
  if ($LASTEXITCODE -eq 0) {
    Write-Output "  PUSH: OK -> branch '$branch' atualizado no remote"
  } else {
    $pushout2 = git -C $r push origin "HEAD:refs/heads/$bkbranch" 2>&1 | Out-String
    if ($LASTEXITCODE -eq 0) {
      Write-Output "  PUSH normal rejeitado (divergencia). BACKUP enviado -> '$bkbranch'"
    } else {
      Write-Output "  PUSH FALHOU TOTALMENTE:"
      Write-Output ($pushout2.Trim() -replace "(?m)^","      ")
    }
  }
}
Write-Output "================================================================"
Write-Output "FIM"

